def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted((list(iv) for iv in intervals), key=lambda x: x[0])

    merged = [sorted_intervals[0][:]]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

import heapq


def toposort(nodes, edges):
    edge_set = set(edges)

    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for source, dest in edge_set:
        adj[source].add(dest)
        in_degree[dest] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')

    for line in text.splitlines():
        line = line.strip()

        if not line or line.startswith('#'):
            continue

        if '=' not in line:
            raise ValueError(f"Invalid line (no '='): {line!r}")

        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key_re.match(key):
            raise ValueError(f"Invalid key: {key!r}")

        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]

        result[key] = value

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                if data == '[DONE]':
                    break
                events.append(data)
            data_lines = []
        elif line.startswith(':'):
            continue
        elif line.startswith('data:'):
            value = line[5:]
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)
        else:
            continue

    return events

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Handles extremely large attempt values (e.g. 10**9) without
    constructing huge integers or overflowing float arithmetic.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")

    if base == 0 or cap == 0:
        return 0.0

    if base >= cap:
        return float(cap)

    # log2(base * 2**attempt) == log2(base) + attempt
    # If that already meets or exceeds log2(cap), the answer is cap.
    if math.log2(base) + attempt >= math.log2(cap):
        return float(cap)

    # Here base * 2**attempt < cap, so the result is strictly less than
    # cap and cannot overflow.  math.ldexp computes x * 2**i in a single
    # floating-point operation without an intermediate overflow.
    return float(min(cap, math.ldexp(base, attempt)))

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError(f"Queued reservation {q} exceeds total budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    remaining = []
    blocked = False

    for q in queued:
        if not blocked and remaining_slots > 0 and remaining_budget >= q:
            admitted.append(q)
            remaining_slots -= 1
            remaining_budget -= q
        else:
            blocked = True
            remaining.append(q)

    return (admitted, remaining)
